from typing import List

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        digits = s[1:-1]

        def valid_numbers(t: str) -> List[str]:
            res = []
            n = len(t)

            if n == 1 or t[0] != '0':
                res.append(t)

            for i in range(1, n):
                left, right = t[:i], t[i:]
                if (left == "0" or not left.startswith("0")) and not right.endswith("0"):
                    res.append(left + "." + right)

            return res

        ans = []
        for i in range(1, len(digits)):
            left_parts = valid_numbers(digits[:i])
            right_parts = valid_numbers(digits[i:])

            for left in left_parts:
                for right in right_parts:
                    ans.append(f"({left}, {right})")

        return ans
