from typing import List

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        roof = m * n

        parent = list(range(roof + 1))
        size = [1] * (roof + 1)

        def index(r: int, c: int) -> int:
            return r * n + c

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        remaining = [row[:] for row in grid]
        for r, c in hits:
            if remaining[r][c] == 1:
                remaining[r][c] = 0

        for r in range(m):
            for c in range(n):
                if remaining[r][c] == 1:
                    curr = index(r, c)
                    if r == 0:
                        union(curr, roof)
                    if r > 0 and remaining[r - 1][c] == 1:
                        union(curr, index(r - 1, c))
                    if c > 0 and remaining[r][c - 1] == 1:
                        union(curr, index(r, c - 1))

        result = [0] * len(hits)
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        for i in range(len(hits) - 1, -1, -1):
            r, c = hits[i]

            if grid[r][c] == 0:
                continue

            before = size[find(roof)]
            remaining[r][c] = 1
            curr = index(r, c)

            if r == 0:
                union(curr, roof)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and remaining[nr][nc] == 1:
                    union(curr, index(nr, nc))

            after = size[find(roof)]
            result[i] = max(0, after - before - 1)

        return result
```

