from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}

        for x in arr:
            dp[x] = 1
            for y in arr:
                if y >= x:
                    break
                if x % y == 0:
                    z = x // y
                    if z in dp:
                        dp[x] = (dp[x] + dp[y] * dp[z]) % MOD

        return sum(dp.values()) % MOD
