class Solution:
    def isCousins(self, root: Optional[TreeNode], x: int, y: int) -> bool:
        queue = [(root, None)]

        while queue:
            next_queue = []
            parent_x = parent_y = None

            for node, parent in queue:
                if node.val == x:
                    parent_x = parent
                if node.val == y:
                    parent_y = parent

                if node.left:
                    next_queue.append((node.left, node))
                if node.right:
                    next_queue.append((node.right, node))

            if parent_x or parent_y:
                return parent_x is not None and parent_y is not None and parent_x != parent_y

            queue = next_queue

        return False
