class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        def is_valid(string: str) -> bool:
            balance = 0
            for ch in string:
                if ch == '(':
                    balance += 1
                elif ch == ')':
                    balance -= 1
                    if balance < 0:
                        return False
            return balance == 0

        level = {s}

        while level:
            valid = [string for string in level if is_valid(string)]
            if valid:
                return valid

            next_level = set()
            for string in level:
                for i, ch in enumerate(string):
                    if ch not in '()':
                        continue
                    if i > 0 and string[i] == string[i - 1]:
                        continue
                    next_level.add(string[:i] + string[i + 1:])

            level = next_level

        return [""]
