        prefix1 = [[0] * 26 for _ in range(n + 1)]
        prefix2 = [[0] * 26 for _ in range(n + 1)]

        for i in range(n):
            prefix1[i + 1] = prefix1[i].copy()
            prefix1[i + 1][ord(s1[i]) - ord('a')] += 1

            prefix2[i + 1] = prefix2[i].copy()
            prefix2[i + 1][ord(s2[i]) - ord('a')] += 1

        def same_chars(i: int, j: int, length: int) -> bool:
            for c in range(26):
                if prefix1[i + length][c] - prefix1[i][c] != prefix2[j + length][c] - prefix2[j][c]:
                    return False
            return True

        @lru_cache(None)
