from typing import List

class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        unique = set(result)
        for word in words:
            unique.update(word)
        if len(unique) > 10:
            return False

        max_word_len = max(len(word) for word in words)
        if len(result) < max_word_len or len(result) > max_word_len + 1:
            return False

        nonzero = set()
        for word in words:
            if len(word) > 1:
                nonzero.add(ord(word[0]) - ord('A'))
        if len(result) > 1:
            nonzero.add(ord(result[0]) - ord('A'))

        max_len = max(max_word_len, len(result))
        rev_words = [word[::-1] for word in words]
        rev_result = result[::-1]

        columns = []
        for pos in range(max_len):
            counts = {}
            for word in rev_words:
                if pos < len(word):
                    idx = ord(word[pos]) - ord('A')
                    counts[idx] = counts.get(idx, 0) + 1
            columns.append(list(counts.items()))

        assign = [-1] * 26
        used = [False] * 10

        def dfs_col(pos: int, carry: int) -> bool:
            if pos == max_len:
                return carry == 0
            return dfs_row(pos, 0, carry)

        def dfs_row(pos: int, row: int, total: int) -> bool:
            if row == len(columns[pos]):
                digit = total % 10
                next_carry = total // 10

                if pos >= len(rev_result):
                    if digit != 0:
                        return False
                    return dfs_col(pos + 1, next_carry)

                idx = ord(rev_result[pos]) - ord('A')
                if assign[idx] != -1:
                    if assign[idx] != digit:
                        return False
                    return dfs_col(pos + 1, next_carry)

                if used[digit] or (digit == 0 and idx in nonzero):
                    return False

                assign[idx] = digit
                used[digit] = True
                if dfs_col(pos + 1, next_carry):
                    return True
                used[digit] = False
                assign[idx] = -1
                return False

            idx, count = columns[pos][row]
            if assign[idx] != -1:
                return dfs_row(pos, row + 1, total + assign[idx] * count)

            for digit in range(10):
                if used[digit] or (digit == 0 and idx in nonzero):
                    continue

                assign[idx] = digit
                used[digit] = True
                if dfs_row(pos, row + 1, total + digit * count):
                    return True
                used[digit] = False
                assign[idx] = -1

            return False

        return dfs_col(0, 0)
